type Entry<V> = { value?: V; expiresAt: number; inflight?: Promise<V> };
const cache = new Map<string, Entry<Entity>>();

export async function getOrLoad<V>(key: string, load: () => Promise<V>, ttlMs: number): Promise<V> {
  const hit = cache.get(key);
  if (hit?.value !== undefined && hit.expiresAt > Date.now()) return hit.value as V;
  if (hit?.inflight) return hit.inflight;
  const inflight = load()
    .then(v => { cache.set(key, { value: v, expiresAt: Date.now() + ttlMs }); return v; })
    .catch(e => { cache.delete(key); throw e; });
  cache.set(key, { expiresAt: 0, inflight });   // never cache a rejected promise
  return inflight;
}
