import { LRUCache } from 'lru-cache';

const cache = new LRUCache<string, Entity>({ max: 5_000, ttl: 5 * 60_000 });

export const read = (id: string) => cache.fetch(`entity:${id}`, () => store.find(id));
export async function update(e: Entity): Promise<void> {
  await store.save(e);                 // source of truth first
  cache.delete(`entity:${e.id}`);      // then invalidate
}
